/*updateBulkQuotationtNotice_2*/
UPDATE KEP_BURQ_NOTC
SET NOTICE_STATUS = #{NOTICE_STATUS},
	NOTICE_REMARK = #{NOTICE_REMARK},
	CHANGE_DATE = SYSDATE,
	CHANGE_USER_ID = #{USER_ID}
WHERE BURQ_NO = #{st_burq_no}
AND SEQ = #{SEQ}
AND NOTICE_TYPE = #{NOTICE_TYPE}


/*updateBulkQuotationtBuyer_1*/
DELETE ICOMCOD2
WHERE TYPE = 'BURQ'
AND CODE = #{st_burq_no}
AND COMPANY_CODE = #{BUYER}


/*updateBulkQuotationtBuyer_2*/
UPDATE ICOMCOD2
SET TEXT1 = #{PROCESS_TYPE},
	TEXT2 = #{PARCEL_YN},
	TEXT3 = #{WAREHOUSE}
WHERE CODE = #{st_burq_no}
AND COMPANY_CODE = #{BUYER}


/*updateBulkQuotationtBuyer_2*/
UPDATE KEP_BURQ_RFQ
SET SM_PROCESS_TYPE = #{PROCESS_TYPE},
	SM_PARCEL_YN = #{PARCEL_YN},
	SM_WAREHOUSE_CODE = #{WAREHOUSE}
WHERE BURQ_NO = #{st_burq_no}
AND NVL(BUYER,BYIT_COMORG_CODE) = #{BUYER}
